package com.hkdn.backend.controller;
import com.hkdn.backend.service.*;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/certificates") public class CertificateDocumentController {private final CertificateService certificates;private final CertificateDocumentService documents;public CertificateDocumentController(CertificateService certificates,CertificateDocumentService documents){this.certificates=certificates;this.documents=documents;}@GetMapping("/{id}/pdf") public ResponseEntity<ByteArrayResource> pdf(@PathVariable UUID id){var data=documents.pdf(certificates.get(id));return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"certificate-"+id+".pdf\"").contentLength(data.length).body(new ByteArrayResource(data));}@GetMapping(value="/{id}/qr",produces=MediaType.IMAGE_PNG_VALUE) public byte[] qr(@PathVariable UUID id){return documents.qr(certificates.get(id).getCode());}}
